#!/usr/bin/env bash
# Build the distributable single-file installer from the editable source.
set -euo pipefail
source_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
output=${1:-"${source_dir}/../../install.sh"}
temp=$(mktemp "${output}.XXXXXX")
trap 'rm -f "$temp"' EXIT
{
    printf '%s\n' '#!/usr/bin/env bash' \
        '# CLASH-AGENT 1.2.0 — generated by scripts/CLASH-AGENT/build.sh.' \
        '# Source: mack-a/v2ray-agent, GNU AGPL v3; see scripts/CLASH-AGENT/LICENSE.' \
        '# Edit the source modules, then rebuild this standalone file.' \
        'set -o pipefail' 'CLASH_AGENT_LIBRARY_ONLY=1' \
        'CLASH_AGENT_ENTRY=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/$(basename -- "${BASH_SOURCE[0]}")'
    for module in upstream system-defaults clash-subscription fail2ban auto-install cloudflare-api cloudflare-config cloudflare-firewall cloudflare-install cloudflare-dns; do
        printf '\n# ---- %s ----\n' "$module"
        cat "${source_dir}/lib/${module}.sh"
        printf '\n'
    done
    awk '/^clash_agent_install_options\(\) \{/ {emit=1} /^if \[\[ \$\{BASH_SOURCE/ {emit=0} emit' "${source_dir}/install.sh"
    printf '\nclash_agent_main "$@"\n'
} >"$temp"
bash -n "$temp"
chmod 755 "$temp"
mv -f "$temp" "$output"
printf 'Built %s\n' "$output"
